import java.util.PriorityQueue

// graph[u] = list of (neighbor, weight)
fun dijkstra(graph: List<List<Pair<Int, Int>>>, source: Int): IntArray {
    val dist = IntArray(graph.size) { Int.MAX_VALUE }
    dist[source] = 0
    val heap = PriorityQueue<IntArray>(compareBy { it[0] })      // [distance, node]
    heap.add(intArrayOf(0, source))

    while (heap.isNotEmpty()) {
        val (d, node) = heap.poll()
        if (d > dist[node]) continue                              // stale entry, a better one was already processed
        for ((next, w) in graph[node]) {
            val nd = d + w
            if (nd < dist[next]) {                                // relax the edge
                dist[next] = nd
                heap.add(intArrayOf(nd, next))
            }
        }
    }
    return dist                                                   // Int.MAX_VALUE means unreachable
}
// Time: O((V + E) log V)   Space: O(V + E)
// Use LongArray and Long weights when distances can exceed about 2 billion

import java.util.PriorityQueue

fun shortestPath(graph: List<List<Pair<Int, Int>>>, source: Int, target: Int): List<Int> {
    val n = graph.size
    val dist = IntArray(n) { Int.MAX_VALUE }
    val parent = IntArray(n) { -1 }                               // previous node on the best path
    dist[source] = 0
    val heap = PriorityQueue<IntArray>(compareBy { it[0] })
    heap.add(intArrayOf(0, source))

    while (heap.isNotEmpty()) {
        val (d, node) = heap.poll()
        if (d > dist[node]) continue
        if (node == target) break                                 // early exit: target is finalized
        for ((next, w) in graph[node]) {
            if (d + w < dist[next]) {
                dist[next] = d + w
                parent[next] = node
                heap.add(intArrayOf(dist[next], next))
            }
        }
    }

    if (dist[target] == Int.MAX_VALUE) return emptyList()         // no path
    val path = ArrayList<Int>()
    var cur = target
    while (cur != -1) {
        path.add(cur)
        cur = parent[cur]
    }
    path.reverse()
    return path
}
// Time: O((V + E) log V)   Space: O(V + E)

// edges[i] = [from, to, weight]
fun bellmanFord(n: Int, edges: Array<IntArray>, source: Int): IntArray? {
    val dist = IntArray(n) { Int.MAX_VALUE }
    dist[source] = 0

    repeat(n - 1) {                                               // a shortest path has at most n - 1 edges
        var changed = false
        for ((u, v, w) in edges) {
            if (dist[u] != Int.MAX_VALUE && dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w
                changed = true
            }
        }
        if (!changed) return dist                                 // early stop: nothing more to improve
    }

    // one more pass: any further improvement means a negative cycle
    for ((u, v, w) in edges) {
        if (dist[u] != Int.MAX_VALUE && dist[u] + w < dist[v]) return null
    }
    return dist
}
// Time: O(V * E)   Space: O(V)
// Returns null when a negative cycle is reachable from the source

fun bellmanFordAtMostK(n: Int, edges: Array<IntArray>, source: Int, k: Int): IntArray {
    var dist = IntArray(n) { Int.MAX_VALUE }
    dist[source] = 0

    repeat(k) {
        val next = dist.copyOf()                                  // read old values, write new ones
        for ((u, v, w) in edges) {
            if (dist[u] != Int.MAX_VALUE && dist[u] + w < next[v]) {
                next[v] = dist[u] + w
            }
        }
        dist = next
    }
    return dist
}
// Time: O(K * E)   Space: O(V)
// Copying the array stops a round from using edges that were just relaxed in the same round

fun floydWarshall(n: Int, edges: Array<IntArray>): Array<LongArray> {
    val inf = Long.MAX_VALUE / 4                                  // large, but sums do not overflow
    val dist = Array(n) { LongArray(n) { inf } }
    for (i in 0 until n) dist[i][i] = 0
    for ((u, v, w) in edges) {                                    // directed edges
        dist[u][v] = minOf(dist[u][v], w.toLong())
    }

    for (k in 0 until n) {                                        // k (the middle node) must be the OUTER loop
        for (i in 0 until n) {
            for (j in 0 until n) {
                if (dist[i][k] + dist[k][j] < dist[i][j]) {
                    dist[i][j] = dist[i][k] + dist[k][j]
                }
            }
        }
    }
    return dist
}
// Time: O(V³)   Space: O(V²)
// A negative value on the diagonal dist[i][i] < 0 means a negative cycle

fun zeroOneBfs(graph: List<List<Pair<Int, Int>>>, source: Int): IntArray {
    val dist = IntArray(graph.size) { Int.MAX_VALUE }
    val deque = ArrayDeque<Int>()
    dist[source] = 0
    deque.addFirst(source)

    while (deque.isNotEmpty()) {
        val node = deque.removeFirst()
        for ((next, w) in graph[node]) {
            if (dist[node] + w < dist[next]) {
                dist[next] = dist[node] + w
                if (w == 0) deque.addFirst(next)                  // free move: process right away
                else deque.addLast(next)
            }
        }
    }
    return dist
}
// Time: O(V + E)   Space: O(V)

fun dagShortestPath(n: Int, edges: Array<IntArray>, source: Int): IntArray {
    val graph = List(n) { mutableListOf<Pair<Int, Int>>() }
    val indegree = IntArray(n)
    for ((u, v, w) in edges) {
        graph[u].add(Pair(v, w))
        indegree[v]++
    }
    val queue = ArrayDeque<Int>()
    for (i in 0 until n) if (indegree[i] == 0) queue.addLast(i)

    val dist = IntArray(n) { Int.MAX_VALUE }
    dist[source] = 0
    while (queue.isNotEmpty()) {
        val u = queue.removeFirst()
        for ((v, w) in graph[u]) {
            if (dist[u] != Int.MAX_VALUE && dist[u] + w < dist[v]) dist[v] = dist[u] + w
            indegree[v]--
            if (indegree[v] == 0) queue.addLast(v)
        }
    }
    return dist
}
// Time: O(V + E)   Space: O(V + E)
// Works with negative weights because every node is finalized after all its predecessors

import java.util.PriorityQueue

fun networkDelayTime(times: Array<IntArray>, n: Int, k: Int): Int {
    val graph = List(n + 1) { mutableListOf<Pair<Int, Int>>() }  // nodes are 1-indexed
    for ((u, v, w) in times) graph[u].add(Pair(v, w))

    val dist = IntArray(n + 1) { Int.MAX_VALUE }
    dist[k] = 0
    val heap = PriorityQueue<IntArray>(compareBy { it[0] })
    heap.add(intArrayOf(0, k))
    while (heap.isNotEmpty()) {
        val (d, node) = heap.poll()
        if (d > dist[node]) continue
        for ((next, w) in graph[node]) {
            if (d + w < dist[next]) {
                dist[next] = d + w
                heap.add(intArrayOf(dist[next], next))
            }
        }
    }

    var answer = 0
    for (i in 1..n) {
        if (dist[i] == Int.MAX_VALUE) return -1                   // some node is unreachable
        answer = maxOf(answer, dist[i])                           // the signal reaches everyone at the max distance
    }
    return answer
}
// Time: O((V + E) log V)   Space: O(V + E)

import java.util.PriorityQueue
import kotlin.math.abs

fun minimumEffortPath(heights: Array<IntArray>): Int {
    val rows = heights.size
    val cols = heights[0].size
    val dirs = arrayOf(intArrayOf(1, 0), intArrayOf(-1, 0), intArrayOf(0, 1), intArrayOf(0, -1))
    val effort = Array(rows) { IntArray(cols) { Int.MAX_VALUE } }
    effort[0][0] = 0
    val heap = PriorityQueue<IntArray>(compareBy { it[0] })       // [effort, row, col]
    heap.add(intArrayOf(0, 0, 0))

    while (heap.isNotEmpty()) {
        val (e, r, c) = heap.poll()
        if (r == rows - 1 && c == cols - 1) return e
        if (e > effort[r][c]) continue
        for ((dr, dc) in dirs) {
            val nr = r + dr
            val nc = c + dc
            if (nr in 0 until rows && nc in 0 until cols) {
                val ne = maxOf(e, abs(heights[nr][nc] - heights[r][c]))   // path cost is the largest step
                if (ne < effort[nr][nc]) {
                    effort[nr][nc] = ne
                    heap.add(intArrayOf(ne, nr, nc))
                }
            }
        }
    }
    return 0
}
// Time: O(rows * cols * log(rows * cols))   Space: O(rows * cols)
// Binary search on the answer with a BFS check is an alternative

fun findCheapestPrice(n: Int, flights: Array<IntArray>, src: Int, dst: Int, k: Int): Int {
    var prices = IntArray(n) { Int.MAX_VALUE }
    prices[src] = 0

    repeat(k + 1) {                                               // k stops means k + 1 flights
        val next = prices.copyOf()
        for ((from, to, price) in flights) {
            if (prices[from] != Int.MAX_VALUE && prices[from] + price < next[to]) {
                next[to] = prices[from] + price
            }
        }
        prices = next
    }
    return if (prices[dst] == Int.MAX_VALUE) -1 else prices[dst]
}
// Time: O(K * E)   Space: O(V)
// Plain Dijkstra can fail here because the cheapest route may use too many stops

import java.util.PriorityQueue

fun maxProbability(n: Int, edges: Array<IntArray>, succProb: DoubleArray, start: Int, end: Int): Double {
    val graph = List(n) { mutableListOf<Pair<Int, Double>>() }
    for ((i, e) in edges.withIndex()) {
        graph[e[0]].add(Pair(e[1], succProb[i]))
        graph[e[1]].add(Pair(e[0], succProb[i]))
    }
    val best = DoubleArray(n)
    best[start] = 1.0
    val heap = PriorityQueue<Pair<Double, Int>>(compareByDescending { it.first })
    heap.add(Pair(1.0, start))

    while (heap.isNotEmpty()) {
        val (p, node) = heap.poll()
        if (node == end) return p
        if (p < best[node]) continue                              // stale entry
        for ((next, prob) in graph[node]) {
            val np = p * prob
            if (np > best[next]) {
                best[next] = np
                heap.add(Pair(np, next))
            }
        }
    }
    return 0.0
}
// Time: O((V + E) log V)   Space: O(V + E)
// Works because every probability is at most 1, so extending a path never improves it

fun findTheCity(n: Int, edges: Array<IntArray>, distanceThreshold: Int): Int {
    val inf = 1_000_000_000                                       // 2 * inf still fits in Int
    val dist = Array(n) { IntArray(n) { inf } }
    for (i in 0 until n) dist[i][i] = 0
    for ((a, b, w) in edges) {
        dist[a][b] = w
        dist[b][a] = w                                            // undirected
    }

    for (k in 0 until n) {
        for (i in 0 until n) {
            for (j in 0 until n) {
                if (dist[i][k] + dist[k][j] < dist[i][j]) dist[i][j] = dist[i][k] + dist[k][j]
            }
        }
    }

    var bestCity = -1
    var fewest = Int.MAX_VALUE
    for (i in 0 until n) {
        var count = 0
        for (j in 0 until n) {
            if (i != j && dist[i][j] <= distanceThreshold) count++
        }
        if (count <= fewest) {                                    // <= prefers the larger index on ties
            fewest = count
            bestCity = i
        }
    }
    return bestCity
}
// Time: O(n³)   Space: O(n²)

import java.util.PriorityQueue

fun countPaths(n: Int, roads: Array<IntArray>): Int {
    val mod = 1_000_000_007L
    val graph = List(n) { mutableListOf<Pair<Int, Long>>() }
    for ((u, v, t) in roads) {
        graph[u].add(Pair(v, t.toLong()))
        graph[v].add(Pair(u, t.toLong()))
    }

    val dist = LongArray(n) { Long.MAX_VALUE }
    val ways = LongArray(n)
    dist[0] = 0
    ways[0] = 1
    val heap = PriorityQueue<Pair<Long, Int>>(compareBy { it.first })
    heap.add(Pair(0L, 0))

    while (heap.isNotEmpty()) {
        val (d, node) = heap.poll()
        if (d > dist[node]) continue
        for ((next, w) in graph[node]) {
            val nd = d + w
            if (nd < dist[next]) {                                // strictly better: reset the count
                dist[next] = nd
                ways[next] = ways[node]
                heap.add(Pair(nd, next))
            } else if (nd == dist[next]) {                        // equally good: add the new routes
                ways[next] = (ways[next] + ways[node]) % mod
            }
        }
    }
    return (ways[n - 1] % mod).toInt()
}
// Time: O((V + E) log V)   Space: O(V + E)

fun minimumObstacles(grid: Array<IntArray>): Int {
    val rows = grid.size
    val cols = grid[0].size
    val dirs = arrayOf(intArrayOf(1, 0), intArrayOf(-1, 0), intArrayOf(0, 1), intArrayOf(0, -1))
    val dist = Array(rows) { IntArray(cols) { Int.MAX_VALUE } }
    dist[0][0] = 0
    val deque = ArrayDeque<IntArray>()
    deque.addFirst(intArrayOf(0, 0))

    while (deque.isNotEmpty()) {
        val (r, c) = deque.removeFirst()
        for ((dr, dc) in dirs) {
            val nr = r + dr
            val nc = c + dc
            if (nr in 0 until rows && nc in 0 until cols) {
                val cost = dist[r][c] + grid[nr][nc]              // entering an obstacle costs 1
                if (cost < dist[nr][nc]) {
                    dist[nr][nc] = cost
                    if (grid[nr][nc] == 0) deque.addFirst(intArrayOf(nr, nc))
                    else deque.addLast(intArrayOf(nr, nc))
                }
            }
        }
    }
    return dist[rows - 1][cols - 1]
}
// Time: O(rows * cols)   Space: O(rows * cols)

fun shortestPath(grid: Array<IntArray>, k: Int): Int {
    val rows = grid.size
    val cols = grid[0].size
    if (rows == 1 && cols == 1) return 0
    val dirs = arrayOf(intArrayOf(1, 0), intArrayOf(-1, 0), intArrayOf(0, 1), intArrayOf(0, -1))
    val visited = Array(rows) { Array(cols) { BooleanArray(k + 1) } }   // state = (row, col, removals left)
    val queue = ArrayDeque<IntArray>()
    queue.addLast(intArrayOf(0, 0, k))
    visited[0][0][k] = true

    var steps = 0
    while (queue.isNotEmpty()) {
        steps++
        repeat(queue.size) {
            val (r, c, left) = queue.removeFirst()
            for ((dr, dc) in dirs) {
                val nr = r + dr
                val nc = c + dc
                if (nr !in 0 until rows || nc !in 0 until cols) continue
                val remaining = left - grid[nr][nc]
                if (remaining < 0 || visited[nr][nc][remaining]) continue
                if (nr == rows - 1 && nc == cols - 1) return steps
                visited[nr][nc][remaining] = true
                queue.addLast(intArrayOf(nr, nc, remaining))
            }
        }
    }
    return -1
}
// Time: O(rows * cols * k)   Space: O(rows * cols * k)
// When the state has extra information, the visited table needs that extra dimension

fun shortestAlternatingPaths(n: Int, redEdges: Array<IntArray>, blueEdges: Array<IntArray>): IntArray {
    val graph = Array(2) { List(n) { mutableListOf<Int>() } }     // 0 = red, 1 = blue
    for ((a, b) in redEdges) graph[0][a].add(b)
    for ((a, b) in blueEdges) graph[1][a].add(b)

    val dist = IntArray(n) { -1 }
    val visited = Array(2) { BooleanArray(n) }
    val queue = ArrayDeque<IntArray>()                            // [node, color of the last edge, steps]
    queue.addLast(intArrayOf(0, 0, 0))
    queue.addLast(intArrayOf(0, 1, 0))
    visited[0][0] = true
    visited[1][0] = true

    while (queue.isNotEmpty()) {
        val (node, color, steps) = queue.removeFirst()
        if (dist[node] == -1) dist[node] = steps                  // first arrival is the shortest
        val nextColor = 1 - color                                 // the next edge must use the other color
        for (next in graph[nextColor][node]) {
            if (!visited[nextColor][next]) {
                visited[nextColor][next] = true
                queue.addLast(intArrayOf(next, nextColor, steps + 1))
            }
        }
    }
    return dist
}
// Time: O(V + E)   Space: O(V + E)

import kotlin.math.ln

// rates[i][j] = amount of currency j you get for 1 unit of currency i
fun hasArbitrage(n: Int, rates: Array<DoubleArray>): Boolean {
    // A cycle with product of rates > 1 is a cycle with sum of -ln(rate) < 0
    val dist = DoubleArray(n)                                     // all zeros acts like a virtual source
    for (iteration in 0 until n) {
        var changed = false
        for (i in 0 until n) {
            for (j in 0 until n) {
                if (i == j) continue
                val w = -ln(rates[i][j])
                if (dist[i] + w < dist[j] - 1e-12) {
                    dist[j] = dist[i] + w
                    changed = true
                }
            }
        }
        if (!changed) return false                                // settled: no negative cycle
    }
    return true                                                   // still improving after n rounds
}
// Time: O(n³)   Space: O(n)
